import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address actor) public {
        // Restrict to admissible domain: actor cannot be zero address, amounts non-zero and within bounds
        vm.assume(actor != address(0));
        vm.assume(depositAmount > 0 && depositAmount < type(uint128).max);
        vm.assume(withdrawAmount > 0 && withdrawAmount < type(uint128).max);

        // Fund actor and perform deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.deposit{value: depositAmount}();

        // Perform withdraw: this may revert in reference, succeed in mutant
        vm.prank(actor);
        try c.withdraw(withdrawAmount) {
            // withdrawal succeeded
        } catch {
            // withdrawal failed
        }

        // Invariant: contract's Ether balance must be at least the sum of all balances.
        // Since balances are internal, we infer from the contract's own balance, which is public via address(c).balance.
        // The reference always satisfies: address(c).balance >= sum of all balances (which equals total deposits minus total successful withdrawals).
        // Because we have only one actor, the sum of balances is at most depositAmount - successfully withdrawn amount (if withdraw succeeded).
        // If withdraw succeeded, the balance was deducted, so address(c).balance should be depositAmount - withdrawAmount.
        // If withdraw failed, balance was not deducted, so address(c).balance = depositAmount.
        // In the buggy version, a withdraw of any amount succeeds even if insufficient balance, deducting more than sent,
        // making address(c).balance < depositAmount - withdrawAmount.
        // So the invariant: address(c).balance >= depositAmount - (withdrawSucceeded ? withdrawAmount : 0).
        // We compute withdrawSucceeded by checking if the balance changed appropriately.
        // We must read c's public surface: there is no getter for balances, but we can use address(c).balance as the observable invariant.
        // However, we cannot observe individual balances. Instead, we note that the sum of all balances cannot exceed the contract's Ether balance.
        // To assert this without internal state, we consider the single-actor scenario: after deposit and attempted withdraw,
        // the actor's balance is at most address(c).balance. Since no other actor is involved, the total balance is the actor's balance.
        // So address(c).balance >= (depositAmount - (withdrawSucceeded ? withdrawAmount : 0)).
        // We need to determine if withdraw succeeded. We can check if the contract's balance decreased by withdrawAmount.
        uint256 contractBalance = address(c).balance;
        bool withdrawSucceeded = (contractBalance < depositAmount);
        uint256 expectedMinimum = depositAmount - (withdrawSucceeded ? withdrawAmount : 0);
        assertTrue(contractBalance >= expectedMinimum);
    }
}

