pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 withdrawAmount, address actor) public {
        // Restrict to practical values
        bound(amount, 1 wei, 100 ether);
        bound(withdrawAmount, 1 wei, 100 ether);
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));

        // Setup actor with some ETH
        vm.deal(actor, 100 ether);
        vm.prank(actor);
        c.deposit{value: amount}();

        // Try to withdraw; record if it succeeds or reverts
        uint256 balanceBeforeEth = address(c).balance;
        uint256 balanceBeforeActor = balancesOf(actor);
        bool ok;
        vm.prank(actor);
        try c.withdraw(withdrawAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Re-query the values
        uint256 balanceAfterEth = address(c).balance;
        uint256 balanceAfterActor = balancesOf(actor);

        // Invariant: if withdrawal succeeded, the ETH balance must have decreased exactly by the amount,
        // and the user's internal balance must have decreased exactly by the same amount.
        // In the correct contract, this always holds. In the mutant (without require), a withdrawal can
        // succeed even with insufficient balance, causing an ETH drain and arithmetic underflow in balances,
        // breaking the relation.
        if (ok) {
            assertEq(balanceBeforeEth - balanceAfterEth, withdrawAmount, "ETH balance must decrease by withdrawal amount");
            assertEq(balanceBeforeActor - balanceAfterActor, withdrawAmount, "User balance must decrease by withdrawal amount");
        } else {
            // If it reverted, balances and ETH should be unchanged
            assertEq(balanceAfterEth, balanceBeforeEth, "No ETH should be sent on revert");
            assertEq(balanceAfterActor, balanceBeforeActor, "User balance unchanged on revert");
        }
    }

    function balancesOf(address user) internal view returns (uint256) {
        // Access public mapping via auto-generated getter
        return c.balances(user);
    }
}

