        vm.prank(actor);
        c.deposit{value: amount}();

        // First withdraw: withdraw full amount
        vm.prank(actor);
        c.withdraw(amount);

        // Second withdraw: withdraw the original balance minus first withdraw (should be 0, so revert)
        // But we actually check if a second withdraw of the original balance fails (it should succeed for bug, revert for correct)
        // Here we instead do a different approach: after first withdraw, balance is 0. A second withdraw of dust should revert.
        // But to distinguish: if bug allows first withdraw to not deduct, balance is still amount, so second withdraw of dust succeeds.
        // So we test: second call to withdraw(dust) should revert for reference, succeed for bug.
        // However, the hint says: after a withdraw, a third withdraw of even 1 wei should revert.
        // We'll do: first withdraw(amount). Then withdraw(amount) again (double spend). For reference should revert (balance 0).
        // For bug, succeeds and balance becomes 0. Then a third withdraw of dust should revert for reference (balance 0), but for bug?
        // Bug doesn't deduct, so after two withdraws, balance is still amount. Third withdraw of dust succeeds for bug, reverts for reference.
        // Let's do three withdraws.

        // First withdraw
        vm.prank(actor);
        c.withdraw(amount);

        // Second withdraw (should revert for ref, succeed for bug)
        bool secondOk;
        vm.prank(actor);
        try c.withdraw(amount) { secondOk = true; } catch { secondOk = false; }

        // If second fails (ref), we don't need third, but if second succeeds (bug), we need third.
        // To make assertion uniform, we always attempt a third withdraw of dust after two withdraws.
        // For ref, second fails, so state unchanged, third still fails. For bug, second succeeds, balance still amount, so third also succeeds.
        // So we just do three withdraws unconditionally and see if third succeeds.
        // But if second fails, the third call must be in same pranked context, but we must reset prank.
        // We'll do:
        // first withdraw(amount)
        // second withdraw(amount) - ignore result
        // third withdraw(dust) - this is the one we test: ref always reverts, bug succeeds (if second succeeded)

        // Actually simpler: after first withdraw, reflect that balance is zero in ref, but amount in bug.
        // So just check if a second withdraw of any positive amount succeeds: bug it does, ref it doesn't.
        // But the problem says approaches like "after a withdraw, calling withdraw again with the same amount should revert" were tried.
        // We need to avoid that. Instead: after first withdraw, a second withdraw of _original balance minus first amount_ should succeed (0), and a third of dust reverts.
        // Since original balance minus first amount is 0, withdraw(0) reverts anyway. So we need a different sequence.
        // Let's use: deposit(2*amount). withdraw(amount). For ref, balance now amount. For bug, balance still 2*amount.
        // Then withdraw(amount) again. Ref: balance becomes 0. Bug: balance still 2*amount (no deduction).
        // Then withdraw(dust). Ref: reverts (balance 0). Bug: succeeds (balance 2*amount).
        // So the third withdraw distinguish.

        vm.prank(actor);
        c.deposit{value: amount}();
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        c.withdraw(amount);
        vm.prank(actor);
        c.withdraw(amount); // ignore result

        bool thirdOk;
        vm.prank(actor);
        try c.withdraw(dust) { thirdOk = true; } catch { thirdOk = false; }

        assertTrue(thirdOk == false);
    }
}

